async def async_create_fix_flow(
    hass: HomeAssistant, issue_id: str, data: dict[str, str] | None
) -> RepairsFlow:
    """Create a fix flow for a repair issue."""
    if issue_id.startswith(UNMANAGED_ISSUE_KEY):
        assert data is not None
        return UnmanagedCodeRepairFlow(data)
    if issue_id.startswith("slot_suspended_") and data is not None:
        return ResumeSlotRepairFlow(data)
    if issue_id.startswith(
        (
            "number_of_uses_removed",
            "slot_disabled_",
            "credential_required_",
            # The credential-required issue's id in an older release.
            "pin_required_",
            "slot_suspended_",
            RE_PAIRED_WORK_DROPPED,
        )
    ):
        return AcknowledgeRepairFlow()
